package com.checkon.engagement.presentation;
import static org.assertj.core.api.Assertions.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.authentication;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.testcontainers.service.connection.ServiceConnection;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.http.MediaType;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.test.web.servlet.MockMvc;import org.testcontainers.junit.jupiter.*;import org.testcontainers.postgresql.PostgreSQLContainer;
import com.checkon.account.domain.AccountRole;import com.checkon.account.infrastructure.security.AuthenticatedAccount;import com.checkon.support.RosterTestFixture;
@SpringBootTest @AutoConfigureMockMvc @Testcontainers class EngagementControllerIntegrationTest {
 @Container @ServiceConnection static final PostgreSQLContainer POSTGRES=new PostgreSQLContainer("postgres:18.4");
 static final UUID TEACHER=UUID.fromString("0198e000-0000-7000-8000-000000000001"),OTHER=UUID.fromString("0198e000-0000-7000-8000-000000000002"),STUDENT=UUID.fromString("0198e000-0000-7000-8000-000000000003"),SIGNAL=UUID.fromString("0198e000-0000-7000-8000-000000000004");
 @Autowired MockMvc mvc;@Autowired JdbcTemplate jdbc;UUID alert;
 @BeforeEach void fixture(){jdbc.update("DELETE FROM intervention_reminders");jdbc.update("DELETE FROM interventions");jdbc.update("DELETE FROM engagement_alerts");jdbc.update("DELETE FROM detection_result_evidence");jdbc.update("DELETE FROM detection_signal_results");jdbc.update("DELETE FROM detection_request_attempts");jdbc.update("DELETE FROM detection_runs");jdbc.update("DELETE FROM ai_student_aliases");jdbc.update("DELETE FROM teacher_student_relationships");jdbc.update("DELETE FROM student_profiles");RosterTestFixture.insertTeacher(jdbc,TEACHER);RosterTestFixture.insertTeacher(jdbc,OTHER);Instant n=Instant.parse("2026-08-04T00:00:00Z");jdbc.update("INSERT INTO student_profiles(id,alias,grade,created_at,updated_at) VALUES (?, '학생',1,?,?)",STUDENT,n.atOffset(ZoneOffset.UTC),n.atOffset(ZoneOffset.UTC));jdbc.update("INSERT INTO ai_student_aliases(teacher_id,student_id,alias,created_at) VALUES(?,?,'st_dddddddddddddddddddddddddddddddd',?)",TEACHER,STUDENT,n.atOffset(ZoneOffset.UTC));jdbc.update("INSERT INTO detection_runs(id,teacher_id,analysis_date,week_start,idempotency_key,snapshot_hash,snapshot_payload,status,prepared_at,requested_at,completed_at,ai_execution_id,created_at,updated_at) VALUES(uuidv7(),?,'2026-08-04','2026-08-03','eng-test','sha256:0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef','{}','SUCCEEDED',?,?,?,'exec',?,?)",TEACHER,n.atOffset(ZoneOffset.UTC),n.atOffset(ZoneOffset.UTC),n.atOffset(ZoneOffset.UTC),n.atOffset(ZoneOffset.UTC),n.atOffset(ZoneOffset.UTC));UUID run=jdbc.queryForObject("SELECT id FROM detection_runs WHERE idempotency_key='eng-test'",UUID.class);jdbc.update("INSERT INTO detection_signal_results(id,detection_run_id,external_signal_id,student_ref,class_ref,rule_id,signal_type,display_label,score,rank,lifecycle,brief_text,gate_passed,fallback_used,created_at) VALUES(?,?, 'sig','st_dddddddddddddddddddddddddddddddd','class','R1','RISK','위험',0.8,1,'NEW','근거 요약',true,false,?)",SIGNAL,run,n.atOffset(ZoneOffset.UTC));jdbc.update("INSERT INTO detection_result_evidence(detection_signal_result_id,source_hint,record_id,summary) VALUES(?,'learning_records','record','근거')",SIGNAL);jdbc.update("INSERT INTO engagement_alerts(teacher_id,student_id,detection_signal_result_id,status,created_at,updated_at) VALUES(?,?,?,'PENDING_REVIEW',?,?)",TEACHER,STUDENT,SIGNAL,n.atOffset(ZoneOffset.UTC),n.atOffset(ZoneOffset.UTC));alert=jdbc.queryForObject("SELECT id FROM engagement_alerts",UUID.class);}
 @Test void teacherReviewsCreatesInterventionAndAutomaticReminder()throws Exception{mvc.perform(get("/api/v1/engagement/alerts").with(auth(TEACHER))).andExpect(status().isOk()).andExpect(jsonPath("$[0].status").value("PENDING_REVIEW"));mvc.perform(get("/api/v1/engagement/alerts/{id}",alert).with(auth(TEACHER))).andExpect(status().isOk()).andExpect(jsonPath("$.alertId").value(alert.toString())).andExpect(jsonPath("$.studentId").value(STUDENT.toString())).andExpect(jsonPath("$.ruleId").value("R1")).andExpect(jsonPath("$.signalType").value("RISK")).andExpect(jsonPath("$.displayLabel").value("위험")).andExpect(jsonPath("$.brief").value("근거 요약")).andExpect(jsonPath("$.briefFallback").value(false)).andExpect(jsonPath("$.createdAt").value("2026-08-04T00:00:00Z")).andExpect(jsonPath("$.evidence[0].sourceHint").value("learning_records")).andExpect(jsonPath("$.evidence[0].summary").value("근거"));mvc.perform(post("/api/v1/engagement/alerts/{id}/approval",alert).with(auth(TEACHER))).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("APPROVED"));String body=mvc.perform(post("/api/v1/engagement/alerts/{id}/interventions",alert).with(auth(TEACHER)).contentType(MediaType.APPLICATION_JSON).content("{\"type\":\"CALL\",\"content\":\"상담 진행\"}")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();UUID intervention=UUID.fromString(body.substring(body.indexOf(":\"")+2,body.indexOf("\"",body.indexOf(":\"")+2)));UUID reminder=jdbc.queryForObject("SELECT id FROM intervention_reminders WHERE intervention_id=? AND status='ACTIVE'",UUID.class,intervention);Instant interventionCreated=jdbc.queryForObject("SELECT created_at FROM interventions WHERE id=?",java.time.OffsetDateTime.class,intervention).toInstant();Instant scheduled=jdbc.queryForObject("SELECT scheduled_at FROM intervention_reminders WHERE id=?",java.time.OffsetDateTime.class,reminder).toInstant();assertThat(scheduled).isEqualTo(interventionCreated.plus(Duration.ofDays(7)));mvc.perform(post("/api/v1/engagement/interventions/{id}/reminders",intervention).with(auth(TEACHER)).contentType(MediaType.APPLICATION_JSON).content("{\"scheduledAt\":\"2026-08-05T00:00:00Z\"}")).andExpect(status().isNotFound());mvc.perform(post("/api/v1/engagement/interventions/{id}/cancellation",intervention).with(auth(TEACHER))).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("CANCELLED"));assertThat(jdbc.queryForObject("SELECT status FROM intervention_reminders WHERE id=?",String.class,reminder)).isEqualTo("CANCELLED");}
 @Test void concealsOtherTenantAndRejectsUnauthenticatedOrParent()throws Exception{mvc.perform(get("/api/v1/engagement/alerts/{id}",alert).with(auth(OTHER))).andExpect(status().isNotFound());mvc.perform(get("/api/v1/engagement/alerts")).andExpect(status().isUnauthorized());mvc.perform(get("/api/v1/engagement/alerts").with(authentication(UsernamePasswordAuthenticationToken.authenticated(new AuthenticatedAccount(UUID.randomUUID(),AccountRole.PARENT,null,UUID.randomUUID()),null,List.of(new SimpleGrantedAuthority("ROLE_PARENT")))))).andExpect(status().isForbidden());}
 @Test void rejectsMalformedEnumAndContradictoryDecision()throws Exception{mvc.perform(get("/api/v1/engagement/alerts?status=NOPE").with(auth(TEACHER))).andExpect(status().isBadRequest());mvc.perform(post("/api/v1/engagement/alerts/{id}/rejection",alert).with(auth(TEACHER)).contentType(MediaType.APPLICATION_JSON).content("{bad" )).andExpect(status().isBadRequest());mvc.perform(post("/api/v1/engagement/alerts/{id}/approval",alert).with(auth(TEACHER))).andExpect(status().isOk());mvc.perform(post("/api/v1/engagement/alerts/{id}/rejection",alert).with(auth(TEACHER)).contentType(MediaType.APPLICATION_JSON).content("{\"note\":\"아님\"}")).andExpect(status().isConflict());}
 private org.springframework.test.web.servlet.request.RequestPostProcessor auth(UUID t){return authentication(UsernamePasswordAuthenticationToken.authenticated(new AuthenticatedAccount(UUID.randomUUID(),AccountRole.TEACHER,t,UUID.randomUUID()),null,List.of(new SimpleGrantedAuthority("ROLE_TEACHER"))));}
}
